import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes{public static void main(String[]args)throws Exception{Map<String,byte[]> data=new TreeMap<>();try(ZipFile z=new ZipFile(args[0])){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();data.put(e.getName(),z.getInputStream(e).readAllBytes());}}String path="dev/zomboid/remains/ZombieRemainsLoot.class";ClassNode c=new ClassNode();new ClassReader(data.get(path)).accept(c,0);int hooks=0;for(var m:c.methods)for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals("dev/zomboid/remains/MilitaryDrops")&&call.name.equals("extras")){m.instructions.insertBefore(n,new InsnNode(DUP2));m.instructions.insert(n,new MethodInsnNode(INVOKESTATIC,"dev/zomboid/remains/AddonDrops","extras","(Ljava/lang/Object;Ljava/lang/Object;)V",false));hooks++;}if(hooks!=1)throw new IllegalStateException("Expected one corpse loot hook, got "+hooks);ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);data.put(path,w.toByteArray());try(var files=Files.walk(Path.of(args[2]))){for(var p:files.filter(p->p.toString().endsWith(".class")).toList())data.put(Path.of(args[2]).relativize(p).toString(),Files.readAllBytes(p));}int methods=0;for(var entry:data.entrySet())if(entry.getKey().endsWith(".class")){ClassNode n=new ClassNode();new ClassReader(entry.getValue()).accept(n,0);for(var m:n.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0){new Analyzer<BasicValue>(new BasicVerifier()).analyze(n.name,m);methods++;}}try(var z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:data.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}System.out.println("Corpse hook verified; ASM methods: "+methods);}}
